+	const partKinds = ANALYZE_KINDS.filter((kind) => kind.startsWith("part.")) as readonly AnalyzeKind[];
+	const surfacesEnabled = surfaceKinds.every((kind) => kinds[kind]);
+	const partsEnabled = partKinds.every((kind) => kinds[kind]);
