+				if (!cancelled) setFixture(parsedFixture);
+			})
+			.catch((error) => {
+				if (!cancelled) setLoadError(error instanceof Error ? error : new Error(String(error)));
+			});
+		return () => {
+			cancelled = true;
+		};
+	}, []);
+
+	useEffect(() => {
